// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class PackedOperatorComponentRefinementTest {

	@Test
	void incumbentRejectsComponentOnlyOperatorRefinement() {
		TupleExpr source = optional();
		PackedQuery query = PackedQueryCodec.encodeForPlanning(source);
		PackedMemo memo = memo(query);
		PackedIncumbentSearch search = new PackedIncumbentSearch(query, memo, unboundedBudget(), false,
				componentOperatorCosts(PackedRelOp.LEFT_JOIN));

		int rootWinnerId = search.build();

		assertEquals(10.0d, memo.winnerOutputRows(rootWinnerId), 0.0d,
				"A component-only operator estimate cannot replace the complete OPTIONAL rows");
		assertEquals(30.0d, memo.winnerTotalCost(rootWinnerId), 0.0d,
				"A component-only operator estimate cannot replace the complete OPTIONAL work");
	}

	@Test
	void selectedContextualizerRejectsComponentOnlyOperatorRefinement() {
		TupleExpr source = optional();
		PackedQuery query = PackedQueryCodec.encodeForPlanning(source);
		PackedMemo memo = memo(query);
		PackedIncumbentSearch search = new PackedIncumbentSearch(query, memo, unboundedBudget(), false,
				basePatternCosts());
		int rootWinnerId = search.build();
		PackedSelectedPlanContextualizer contextualizer = new PackedSelectedPlanContextualizer(query, memo,
				unboundedBudget(), componentOperatorCosts(PackedRelOp.LEFT_JOIN), search.selectedRowsByGroup());

		int contextualWinnerId = contextualizer.contextualize(rootWinnerId);

		assertEquals(10.0d, memo.winnerOutputRows(contextualWinnerId), 0.0d,
				"Selected-DAG contextualization must retain the complete OPTIONAL rows");
		assertEquals(30.0d, memo.winnerTotalCost(contextualWinnerId), 0.0d,
				"Selected-DAG contextualization must retain the complete OPTIONAL work");
	}

	@Test
	void rootJoinEnumerationRejectsComponentOnlyOperatorRefinement() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		TupleExpr source = new Join(
				pattern(values, "shared", "urn:left", "leftValue"),
				pattern(values, "shared", "urn:right", "rightValue"));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(source);
		PackedMemo memo = memo(query);
		PackedIncumbentSearch search = new PackedIncumbentSearch(query, memo, unboundedBudget(), false,
				basePatternCosts());
		search.build();
		PackedJoinEnumerator enumerator = new PackedJoinEnumerator(query, memo, search.selectedRowsByGroup(),
				unboundedBudget(), componentOperatorCosts(PackedRelOp.JOIN));

		int workUnits = enumerator.optimizeSequence(query.rootRelId());
		int rootWinnerId = memo.findWinner(memo.logicalGroupId(query.rootRelId()), memo.anyPropertyId(), 0, 0, 0);

		assertTrue(workUnits > 0);
		assertEquals(10.0d, memo.winnerOutputRows(rootWinnerId), 0.0d,
				"Root-join refinement lacks component contributions and must retain the complete join rows");
	}

	@Test
	void contextualFilterComposesComponentRefinementWithUnrelatedPrefix() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern outer = pattern(values, "outer", "urn:outer", "outerValue");
		outer.setResultSizeEstimate(4.0d);
		StatementPattern inner = pattern(values, "inner", "urn:inner", "innerValue");
		inner.setResultSizeEstimate(5.0d);
		Filter filter = new Filter(inner,
				new Compare(Var.of("innerValue"), new ValueConstant(values.createLiteral("excluded")),
						Compare.CompareOp.NE));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Join(outer, filter));
		PackedMemo memo = memo(query);
		PackedIncumbentSearch search = new PackedIncumbentSearch(query, memo, unboundedBudget(), false, null);
		search.build();
		PackedQueryView view = new PackedQueryView(query);
		int outerRelationId = relationWithPredicate(view, "urn:outer");
		int filterRelationId = filterRelation(view);
		PackedCostModel costs = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				if (!query.isStatementPattern(relationId)) {
					return Double.NaN;
				}
				return "urn:outer".equals(predicate(query, relationId)) ? 4.0d : 5.0d;
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.isFilter(relationId)) {
					output.setComponentRows(2.0d, 2.0d);
					output.setReplacesChildWork(true);
					output.setEstimateProvenance("component-filter-test", "operator_feedback");
				}
			}
		};
		PackedJoinEnumerator enumerator = new PackedJoinEnumerator(query, memo, search.selectedRowsByGroup(),
				unboundedBudget(), costs);

		int contextualWinnerId = enumerator.optimizeWithInheritedPrefix(filterRelationId,
				new int[] { outerRelationId }, new double[] { 4.0d }, 1, 4.0d);

		assertEquals(8.0d, memo.winnerOutputRows(contextualWinnerId), 0.0d,
				"The retained four-row outer component must multiply the two-row refined FILTER component");
		assertTrue(memo.winnerTotalCost(contextualWinnerId) >= 10.0d,
				"Component-local work cannot replace the already contextualized FILTER child");
	}

	private static TupleExpr optional() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		return new LeftJoin(
				pattern(values, "shared", "urn:left", "leftValue"),
				pattern(values, "shared", "urn:right", "rightValue"));
	}

	private static PackedCostModel basePatternCosts() {
		return (query, relationId) -> query.isStatementPattern(relationId) ? 10.0d : Double.NaN;
	}

	private static PackedCostModel componentOperatorCosts(int operatorTag) {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? 10.0d : Double.NaN;
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.operatorTag(relationId) == operatorTag) {
					output.setComponentRows(2.0d, 2.0d);
					output.setReplacesChildWork(true);
					output.setEstimateProvenance("component-operator-test", "operator_feedback");
				}
			}
		};
	}

	private static PackedMemo memo(PackedQuery query) {
		int relationCount = query.relationCount();
		return new PackedMemo(query, query.symbolCount(), relationCount, relationCount, 4, relationCount,
				relationCount * 2);
	}

	private static PackedSearchBudget unboundedBudget() {
		return new PackedSearchBudget(Long.MAX_VALUE, Long.MAX_VALUE);
	}

	private static int relationWithPredicate(PackedQueryView query, String predicate) {
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (query.isStatementPattern(relationId) && predicate.equals(predicate(query, relationId))) {
				return relationId;
			}
		}
		throw new AssertionError("Missing statement pattern " + predicate);
	}

	private static int filterRelation(PackedQueryView query) {
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (query.isFilter(relationId)) {
				return relationId;
			}
		}
		throw new AssertionError("Missing FILTER");
	}

	private static String predicate(PackedQueryView query, int relationId) {
		return query.statementPatternValue(relationId, 1).stringValue();
	}

	private static StatementPattern pattern(SimpleValueFactory values, String subject, String predicate,
			String object) {
		return new StatementPattern(Var.of(subject), Var.of("predicate", values.createIRI(predicate)),
				Var.of(object));
	}
}
